          'Trang này vẽ ra một bố cục bàn phím và làm sáng từng phím đúng như trình duyệt báo về. Phím được tô sáng khi bạn giữ và vẫn được đánh dấu sau khi đã thử, nên bạn có thể đi hết bàn phím và thấy ngay phím nào chưa từng phản hồi. Với mỗi lần nhấn, trang còn hiển thị các giá trị thô mà trình duyệt nhận được (giá trị phím, mã vật lý và mã số kiểu cũ) đúng thứ bạn cần khi một phím cho ra ký tự khác với chữ in trên nó.',
