          'Phím báo là đang giữ dù bạn không chạm vào thì phím đó bị kẹt, thường do bụi bẩn dưới nắp phím.',
          'Một số phím tắt bị hệ điều hành giữ lại và không bao giờ đến được bất kỳ trang web nào.',
          'Mã phím cho biết bàn phím thực sự đã gửi gì. Đó là cách phát hiện bố cục sai.',
