          'Điều nó sẽ không làm là giả vờ rằng bước cuối cùng cũng là một phép đo. Đọc ra rằng một phông là phông có chân, tương phản cao, chiều cao chữ x nhỏ, đó là số học. Quyết định rằng tổ hợp ấy chính là cái người ta gọi là thanh lịch, đó là một phán đoán, và nó được viết ra chứ không giấu đi: mỗi kết quả liệt kê những đặc điểm hợp và những đặc điểm lệch, để bạn có thể phản đối lập luận chứ không chỉ phản đối câu trả lời.',
